'use strict';
window.FrontierBootstrap=(()=>{
 let started=false,customLoader=null;
 function failure(error){const host=document.createElement('section');host.className='cloud-adoption';host.innerHTML='<div class="prts-terminal"><h1>旅程資料已受到保護</h1><p id="boot-cloud-error"></p><button id="boot-reload">重新載入</button><p>尚未清空本機或雲端存檔。</p></div>';host.querySelector('p').textContent=error.message||'目前無法安全載入。';host.querySelector('button').onclick=()=>location.reload();document.body.append(host);document.body.classList.remove('booting');document.body.classList.add('identity-mode')}
 async function launch(){if(started)return;started=true;document.body.classList.add('booting');window.FrontierBootProgress?.step(10,'正在讀取旅程與存檔');if(customLoader)return customLoader();const script=document.createElement('script');script.src='save-guard.js?v=claude20';script.onload=()=>FrontierSaveGuard.launch();script.onerror=()=>failure(Error('存檔保護程式載入失敗。'));document.body.append(script)}
 async function authenticated(account,offline=false){try{window.FrontierBootProgress?.step(6,'正在同步博士資料');await FrontierCloud.prepare(account,offline);await launch()}catch(e){failure(e)}}
 async function boot(loader){customLoader=loader||null;if(!window.FrontierDeployment?.cloudEnabled||location.protocol==='file:')return launch();const last=FrontierCloud.lastDoctor();if(navigator.onLine===false&&last)return authenticated(last,true);return FrontierIdentity.boot(authenticated,launch,()=>{const doctor=FrontierCloud.lastDoctor();if(!doctor)return false;authenticated(doctor,true);return true})}
 function status(){const info=window.FrontierCloud?.info(),account=info?.account;if(!account)return;const el=document.querySelector('header .status');if(el)el.textContent=account.label+' · '+({offline:'本機已保存 · 待同步','offline-conflict':'雲端有新進度 · 本機保留','offline-auth':'請重新驗證 · 本機保留','offline-rejected':'雲端未接受 · 本機保留',saving:'同步中',saved:'已同步',ready:'雲端已讀取',conflict:'版本衝突',uncertain:'連線待確認',rejected:'同步未完成，進度保留', 'developer-local':'獨立測試檔'})[info.status]}
 async function logout(){if(!FrontierCloud.info().account)return;try{await FrontierStorage.flush();await FrontierIdentity.api('logout',{});FrontierCloud.forget();location.reload()}catch(e){if(typeof toast==='function')toast(e.message)}}
 async function devices(){try{const result=await FrontierIdentity.api('devices');modal('登入裝置',result.devices.map(d=>'<section class="panel"><b>'+esc(d.current?'目前裝置':'其他裝置')+'</b><p class="tiny muted">'+esc(d.name)+'</p><p>有效至 '+esc(new Date(d.expiresAt).toLocaleString('zh-TW'))+'</p></section>').join('')+'<p class="tiny muted">撤銷其他裝置不刪除雲端進度；那些裝置下次保存時須重新登入。</p>','<button onclick="FrontierBootstrap.revokeOthers()">撤銷其他裝置</button><button onclick="closeModal()">關閉</button>')}catch(e){toast(e.message)}}
 async function revokeOthers(){try{await FrontierIdentity.api('revoke',{});await devices();toast('其他裝置的登入狀態已撤銷。')}catch(e){toast(e.message)}}
 function changePin(){modal('修改六位PIN','<form id="account-pin-form"><label>目前PIN<input id="account-pin-old" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="current-password" required></label><label>新PIN<input id="account-pin-new" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="new-password" required></label><label>再次確認<input id="account-pin-confirm" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="new-password" required></label><p class="tiny muted">修改成功會撤銷其他裝置，保留目前裝置與所有存檔。</p><p id="account-pin-note" role="status"></p><button type="submit">確認修改PIN</button></form>','<button onclick="closeModal()">關閉</button>');const form=document.querySelector('#account-pin-form');form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('[type=submit]');if(button.disabled)return;button.disabled=true;try{await FrontierIdentity.api('pin',{oldPin:form.querySelector('#account-pin-old').value,pin:form.querySelector('#account-pin-new').value,confirmPin:form.querySelector('#account-pin-confirm').value});form.querySelector('#account-pin-note').textContent='PIN已修改，其他裝置已撤銷。'}catch(e){form.querySelector('#account-pin-note').textContent=e.message}finally{form.querySelectorAll('input').forEach(input=>input.value='');button.disabled=false}})}
 function resetAccount(){modal('重啟帳號旅程','<form id="account-restart-form"><p>清除目前帳號的幹員、物資、基建、收藏、戰績及進行中的行動，重新取得初始小隊。博士登入名稱、PIN與復原碼保留。</p><p class="tiny muted">重啟前會保留本機保護副本；其他裝置將登出，避免舊進度覆蓋新旅程。</p><label>目前帳號PIN<input id="account-restart-pin" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="current-password" required></label><label class="row"><input type="checkbox" id="account-restart-confirm" required>我確認清除目前遊戲進度並重新開始</label><p id="account-restart-note" role="alert"></p><button type="submit" class="danger">驗證PIN並重啟</button></form>','<button onclick="closeModal()">取消</button>');const form=document.querySelector('#account-restart-form');form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('[type=submit]'),input=form.querySelector('#account-restart-pin'),note=form.querySelector('#account-restart-note');if(button.disabled||!form.querySelector('#account-restart-confirm').checked)return;button.disabled=true;note.textContent='正在驗證並重啟，請稍候…';try{await FrontierCloud.restart(input.value);note.textContent='旅程已重啟，正在載入初始小隊。';location.reload()}catch(e){note.textContent=e.message}finally{input.value='';button.disabled=false}})}
 async function backups(){try{const account=FrontierCloud.info().account,keys=await FrontierStorage.listBackups(account?.id);modal('本機保護備份','<p>這些副本保留載入雲端前、升級前或沿用匿名旅程前的原始內容；下載不會覆蓋目前進度。</p>'+keys.map((key,i)=>'<button class="full" data-backup-index="'+i+'">下載保護副本 '+(i+1)+'</button>').join('')+(keys.length?'':'<p>目前沒有已建立的保護副本。</p>'),'<button onclick="closeModal()">關閉</button>');document.querySelectorAll('[data-backup-index]').forEach(button=>button.addEventListener('click',async()=>{const raw=await FrontierStorage.readRecord(keys[Number(button.dataset.backupIndex)]);if(raw===null){toast('此副本暫時無法讀取。');return}const url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='界外餘響-本機保護副本.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}))}catch(e){toast(e.message)}}
 window.addEventListener('frontier:boot',()=>{status();if(!FrontierCloud.info().account)return;const accountSection=function(){const info=FrontierCloud.info();return '<section class="panel"><h3>博士帳號與同步</h3><p id="cloud-account-label"></p><p>雲端版本 '+info.revision+'；'+(info.onlineRequired?'斷線仍可繼續遊玩。':info.offline?'進度已存本機，連線後會嘗試同步。':'開發者檔只保存在本機，不上傳。')+'</p><button onclick="FrontierCloud.syncOffline()">同步離線進度</button><button onclick="FrontierBootstrap.devices()">登入裝置</button><button onclick="FrontierBootstrap.changePin()">修改PIN</button><button onclick="FrontierBootstrap.backups()">保護備份</button><button class="danger" onclick="FrontierBootstrap.resetAccount()">重啟帳號／清除進度</button><button onclick="FrontierBootstrap.logout()">登出／切換帳號</button><p class="tiny muted">登出不刪除雲端或本機存檔。其他裝置出現新進度時，會停止覆蓋並保留本機備份。</p></section>'};const oldRender=render;render=function(){oldRender();if(page==='settings')document.querySelector('#app').insertAdjacentHTML('beforeend',accountSection());const label=document.querySelector('#cloud-account-label');if(label)label.textContent=FrontierCloud.info().account.label;status()};render()},{once:true});
 document.addEventListener('frontier:cloud-status',status);document.addEventListener('frontier:committed',status);
 return{boot,launch,authenticated,failure,logout,status,devices,revokeOthers,changePin,backups,resetAccount};
})();

